ADV_cloud_provision.invariants_dsl:
spec CloudProvision {
    field base_ram: Integer {
        value >= 8;
    }
    field instance_count: Integer {
        value IN [1, 2, 4, 8];
    }
    field total_ram: Integer { }

    invariant calc_ram {
        this.total_ram ==
            this.base_ram * this.instance_count;
    }

    field tier: String {
        value IN ["standard", "enterprise"];
    }

    invariant tier_check {
        this.total_ram > 32
            -> this.tier == "enterprise";
    }
}

ADV_membership_and_exclusion.invariants_dsl:
spec PortSelection {
    field allowed_ports: Array<Integer> {
        value == [80, 443, 8080];
    }
    field chosen_port: Integer {
        value IN this.allowed_ports;
    }
    field blocked_port: Integer {
        value NIN this.allowed_ports;
        value >= 1;
        value <= 100;
    }
}

